head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1"
    }, {
        "col1": "a2"
    }, {
        "col1": "a3"
    }, {
        "col1": "a4"
    }, {
        "col1": "a5"
    }];
    main_dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var tabObj = {
        label: "임시화면",
        closable: true,
        openAction: "exist"
    };
    var contObj = {
        frameMode: "wframe",
        scope: true,
        src: "tabControl_wframe_WPFF-370_(WSQ-3938)_sub.xml",
        alwaysDraw: false,
        title: "test",
        dataObject: {
            type: "json",
            name: "param1",
            data: {
                "test1": "d_test11",
                "test2": "d_test22"
            }
        }
    };
    tabControl1.addTab("test111", tabObj, contObj);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_contents_test111_body_input1').value == 'd_test11'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_contents_test111_body_input1').value == 'd_test11'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
